/**
 * Partnerships nav links that render their platform's own logo.
 *
 * Keyed by href rather than by the link's `icon` value because the live
 * navigation is served from Sanity (siteSettings.navigation), where these
 * links still carry the generic icon keys they were seeded with. Matching on
 * the href makes the logos correct for the seeded content and for any later
 * re-seed from src/data/nav-v2.ts, which now names the same marks directly.
 */
const PARTNER_LOGO_BY_HREF: Record<string, string> = {
  '/partnerships/monday-consulting-partner': 'monday',
  '/partnerships/certified-atlassian-partner': 'atlassian',
  '/partnerships/certified-hubspot-partner': 'hubspot',
  '/partnerships/certified-clickup-partner': 'clickup',
  '/partnerships/anthropic-claude-partner': 'anthropic',
  '/partnerships/openai-chatgpt-partner': 'openai',
  '/partnerships/microsoft-copilot-partner': 'copilot',
  '/partnerships/google-gemini-vertex-ai-partner': 'gemini',
  '/partnerships/microsoft-azure-partner': 'azure',
  '/partnerships/supabase-partner': 'supabase',
  '/partnerships/google-cloud-partner': 'googlecloud',
  '/partnerships/aws-partner': 'aws',
  '/partnerships/make-partners': 'make',
  '/partnerships/n8n-integration-partner': 'n8n',
  '/integrations/zapier': 'zapier',
  '/partnerships/langgraph-partner': 'langgraph',
  '/partnerships/clay-partner': 'clay',
  '/partnerships/elevenlabs-partner': 'elevenlabs',
  '/partnerships/vapi-partner': 'vapi',
}

interface NavIconProps {
  iconKey?: string | null
  /** Link target, used to prefer a platform logo over the generic icon key. */
  href?: string | null
  className?: string
}

export function NavIcon({ iconKey, href, className }: NavIconProps) {
  const key = (href && PARTNER_LOGO_BY_HREF[href]) || iconKey
  if (!key) return null
  const Icon = NAV_ICONS[key]
  if (!Icon) return null
  return <Icon className={className} />
}

export const NAV_ICON_KEYS = Object.keys(NAV_ICONS)
